import type { PatenteHistorico } from './Seccion7_6Patentes';

interface FilaPermisoFeria {
  numero: string;
  fecha: string;
  descripcion: string;
  fechaPublicacion: string;
  ultimaActualizacion?: string;
  tieneEfectosGenerales?: string;
  enlaceModificacion?: string;
  tipoNorma?: string;
  nombreTitulo?: string;
}

const crearPermisosFeria = (filas: FilaPermisoFeria[]): PatenteHistorico[] =>
  filas.map(({
    numero,
    fecha,
    descripcion,
    fechaPublicacion,
    ultimaActualizacion = 'Sin Modificaciones',
    tieneEfectosGenerales = 'Sí',
    enlaceModificacion = 'Sin Modificaciones',
    tipoNorma = 'Decretos Exentos',
    nombreTitulo = 'Permiso de Feria Libre'
  }) => ({
    
    tipoNorma,
    denominacion: 'Patentes y Permisos',
    nombreTitulo,
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales,
    ultimaActualizacion,
    descripcion,
    enlacePublicacion: 'PDF',
    enlaceModificacion,
    urlPublicacion: '',
    urlModificacion: ''
  }));

